        if(operation==1)ProgrammableLightConnections.refreshAround(world,POS);if(operation==2)result=blocks[family].onBlockActivated(world,POS,world.states.get(POS),new Player(world),EnumHand.MAIN_HAND,face,.5F,.5F,.5F);if(operation==3&&world.isBlockLoaded(peer))other.setChannelLevel(15);if(operation==4&&world.isBlockLoaded(peer))other.setChannelSignal(false);row.addProperty("result",result);row.add("after",nodes(world,Arrays.asList(POS,peer)));row.add("afterMembers",positions(ProgrammableLightConnections.members(owner,world.states.get(POS))));String text=row.toString();output.println(text);hash.update(text.getBytes(StandardCharsets.UTF_8));rows++;
