        for(int count:new int[]{4095,4096}){NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);List<BlockPos> cells=new ArrayList<>();TileEntityProgrammableLight owner=null;for(int n=0;n<count;n++){BlockPos cell=POS.add(n%64,n/64,0);cells.add(cell);TileEntityProgrammableLight tile=put(world,cell,blocks[0],EnumFacing.NORTH,0,false,n==0?0:1,0);if(n==0)owner=tile;}JsonObject row=new JsonObject();row.addProperty("family",0);row.addProperty("trigger",0);row.addProperty("numeric",false);row.addProperty("variant",18);row.addProperty("operation",0);row.addProperty("count",count);PanelPlane plane=PanelPlane.of(EnumFacing.NORTH);JsonArray directions=new JsonArray();for(EnumFacing direction:new EnumFacing[]{plane.right,plane.right.getOpposite(),plane.up,plane.up.getOpposite()})directions.add(position(new BlockPos(direction.getDirectionVec())));row.add("directions",directions);JsonArray captured=nodes(world,cells);row.add("before",captured);row.add("after",captured);row.add("manualMembers",positions(ProgrammableLightConnections.members(owner,world.states.get(POS))));row.add("powerMembers",positions(powerMembers(owner,world.states.get(POS))));row.add("afterMembers",positions(ProgrammableLightConnections.members(owner,world.states.get(POS))));row.addProperty("result",true);String text=row.toString();output.println(text);hash.update(text.getBytes(StandardCharsets.UTF_8));rows++;}
